1610   if (!match(BO.getOperand(1), m_Constant(Op1FpC)) &&
1611       !match(BO.getOperand(1), m_SIToFP(m_Value(IntOps[1]))) &&
1612       !match(BO.getOperand(1), m_UIToFP(m_Value(IntOps[1]))))
