1619   // different constraints depending on the sign of the cast.
1620   // NB: `(uitofp nneg X)` == `(sitofp nneg X)`.
1621   if (Instruction *R = foldFBinOpOfIntCastsFromSign(BO, /*OpsFromSigned=*/false,
1622                                                     IntOps, Op1FpC, OpsKnown))
1623     return R;
